// Contenuti verificati sul Codice della Strada (D.Lgs. 285/1992) e Regolamento (DPR 495/1992).
const CATS=[
 {id:"P",n:"Segnali di pericolo",col:"#e63946",intro:"I segnali di pericolo hanno forma di triangolo equilatero con il vertice in alto, fondo bianco e bordo rosso. Avvertono di un pericolo vicino. Fuori dai centri abitati sono posti di norma a 150 metri dal pericolo; se la distanza è diversa, lo indica un pannello integrativo. Davanti a un segnale di pericolo bisogna aumentare l'attenzione e moderare la velocità."},
 {id:"R",n:"Segnali di precedenza",col:"#f4a261",intro:"I segnali di precedenza stabiliscono chi deve passare per primo. Hanno forme particolari, così si riconoscono anche da dietro o coperti dalla neve: il triangolo capovolto del Dare precedenza, l'ottagono dello STOP, il quadrato giallo messo sul vertice del Diritto di precedenza."},
 {id:"D",n:"Segnali di divieto",col:"#d62828",intro:"I segnali di divieto sono rotondi, quasi sempre con bordo rosso. Vietano un comportamento. Valgono dal punto in cui sono posti fino al primo incrocio, oppure fino al segnale di fine divieto, salvo diversa indicazione di un pannello integrativo."},
 {id:"O",n:"Segnali di obbligo",col:"#1d4ed8",intro:"I segnali di obbligo sono rotondi con fondo blu e simbolo bianco. Impongono un comportamento: una direzione, un passaggio, un percorso riservato o un'attrezzatura."},
 {id:"I",n:"Segnali di indicazione",col:"#2563eb",intro:"I segnali di indicazione danno informazioni utili per la guida: tipo di strada, servizi, centri abitati, parcheggi. Di solito sono rettangolari o quadrati. Il colore di fondo dipende dal tipo di strada: verde per le autostrade, blu per le strade extraurbane e urbane, bianco in città, marrone per i luoghi turistici."},
 {id:"A",n:"Pannelli integrativi",col:"#64748b",intro:"I pannelli integrativi sono rettangoli bianchi messi sotto un segnale. Ne precisano il significato: la distanza, il tratto di strada interessato, l'orario o le categorie di veicoli a cui il segnale si applica."},
 {id:"S",n:"Semafori e agenti del traffico",col:"#16a34a",intro:"I semafori e i segnali degli agenti regolano il traffico agli incroci. Ricorda la gerarchia dell'articolo 38 del Codice: le segnalazioni degli agenti prevalgono sui semafori e sui segnali stradali, e i semafori prevalgono sui segnali stradali di precedenza."}
];
const SIGNS=[
// ---------------- PERICOLO
{id:"curva_dx",c:"P",n:"Curva pericolosa a destra",t:"Questo è il segnale di curva pericolosa a destra. Preannuncia una curva a destra con scarsa visibilità o pericolosa. Prima della curva devi rallentare, tenere bene la destra e non sorpassare. Si frena prima di entrare in curva, non dentro la curva.",q:[["Il segnale preannuncia una curva a destra pericolosa",1],["Il segnale obbliga a svoltare a destra",0],["In presenza di questo segnale bisogna moderare la velocità prima della curva",1]]},
{id:"curva_sx",c:"P",n:"Curva pericolosa a sinistra",t:"Questo è il segnale di curva pericolosa a sinistra. Avverte che la strada piega a sinistra in modo pericoloso. Devi rallentare prima della curva, tenere la destra della carreggiata e non tagliare la curva invadendo la corsia opposta.",q:[["Il segnale preannuncia una curva pericolosa a sinistra",1],["Il segnale consente di tagliare la curva per avere più visibilità",0]]},
{id:"doppia_dx",c:"P",n:"Doppia curva, la prima a destra",t:"Questo è il segnale di doppia curva con la prima a destra. Preannuncia due curve pericolose consecutive: la prima piega a destra, la seconda a sinistra. Riduci la velocità prima della prima curva e non sorpassare in tutto il tratto.",q:[["Il segnale preannuncia due curve, la prima delle quali verso destra",1],["Il segnale preannuncia una sola curva verso destra",0]]},
{id:"doppia_sx",c:"P",n:"Doppia curva, la prima a sinistra",t:"Questo è il segnale di doppia curva con la prima a sinistra. Preannuncia due curve pericolose ravvicinate: la prima a sinistra, la seconda a destra. Rallenta, tieni la destra e non sorpassare.",q:[["Il segnale preannuncia una doppia curva, la prima a sinistra",1],["In presenza di questo segnale il sorpasso è sempre consigliato per liberarsi dei veicoli lenti",0]]},
{id:"dosso",c:"P",n:"Dosso",t:"Questo è il segnale di dosso. Preannuncia un rilievo della strada che limita la visibilità, oppure un dosso artificiale rallentatore. Devi rallentare, tenerti a destra e non sorpassare, perché oltre il dosso potrebbe arrivare qualcuno che non vedi.",q:[["Il segnale preannuncia un tratto di strada con un rilievo che limita la visibilità",1],["In prossimità del dosso è vietato sorpassare se manca la visibilità",1],["Il segnale indica una cunetta",0]]},
{id:"cunetta",c:"P",n:"Cunetta",t:"Questo è il segnale di cunetta. Preannuncia un avvallamento della strada, cioè un abbassamento brusco del fondo. Passandoci veloce il veicolo può sobbalzare e perdere aderenza. Devi rallentare per tempo.",q:[["Il segnale preannuncia un avvallamento della strada",1],["Il segnale preannuncia un dosso",0]]},
{id:"strett_sim",c:"P",n:"Strettoia simmetrica",t:"Questo è il segnale di strettoia simmetrica. Preannuncia un restringimento della carreggiata su entrambi i lati. Riduci la velocità e fai attenzione ai veicoli che arrivano in senso opposto, perché lo spazio per incrociarsi è minore.",q:[["Il segnale preannuncia un restringimento della carreggiata da entrambi i lati",1],["Il segnale indica che la strada si allarga",0]]},
{id:"strett_dx",c:"P",n:"Strettoia asimmetrica a destra",t:"Questo è il segnale di strettoia asimmetrica a destra. La carreggiata si restringe sul lato destro. Rallenta e spostati con prudenza, controllando chi arriva di fronte.",q:[["Il segnale preannuncia un restringimento della carreggiata sul lato destro",1],["Il segnale preannuncia un restringimento sul lato sinistro",0]]},
{id:"strett_sx",c:"P",n:"Strettoia asimmetrica a sinistra",t:"Questo è il segnale di strettoia asimmetrica a sinistra. La carreggiata si restringe sul lato sinistro. Riduci la velocità e mantieni la tua destra.",q:[["Il segnale preannuncia un restringimento della carreggiata sul lato sinistro",1],["Il segnale indica una curva a sinistra",0]]},
{id:"deformata",c:"P",n:"Strada deformata",t:"Questo è il segnale di strada deformata. Avverte che il fondo stradale è irregolare: buche, ondulazioni, rattoppi. Devi rallentare per non perdere il controllo e non danneggiare il veicolo. Con la strada deformata aumenta anche lo spazio di frenatura.",q:[["Il segnale preannuncia un tratto di strada con fondo irregolare",1],["Il segnale preannuncia un dosso artificiale",0]]},
{id:"sdrucciolevole",c:"P",n:"Strada sdrucciolevole",t:"Questo è il segnale di strada sdrucciolevole. Avverte che il fondo può diventare scivoloso, per esempio con pioggia, ghiaccio, foglie, fango o olio. Devi moderare la velocità, aumentare la distanza di sicurezza ed evitare frenate e sterzate brusche.",q:[["Il segnale preannuncia un tratto di strada che può diventare scivoloso",1],["In presenza di questo segnale bisogna evitare brusche frenate",1],["Il segnale indica una strada con curve a zig zag",0]]},
{id:"banchina",c:"P",n:"Banchina pericolosa",t:"Questo è il segnale di banchina pericolosa. Avverte che la banchina, cioè la striscia ai lati della carreggiata, è cedevole o non praticabile, oppure c'è un dislivello. Non devi salire sulla banchina con le ruote: tieni il veicolo sulla carreggiata.",q:[["Il segnale avverte che la banchina laterale è pericolosa",1],["Il segnale consente di sostare sulla banchina",0]]},
{id:"molo",c:"P",n:"Sbocco su molo o argine",t:"Questo è il segnale di sbocco su molo o su argine. Avverte che la strada finisce su un molo o su un argine, con il pericolo di finire in acqua. Devi rallentare molto e procedere con la massima prudenza, soprattutto di notte o con la nebbia.",q:[["Il segnale avverte del pericolo di cadere in acqua per lo sbocco della strada su un molo",1],["Il segnale indica la vicinanza di un porto turistico",0]]},
{id:"massi",c:"P",n:"Caduta massi",t:"Questo è il segnale di caduta massi. Avverte che dal versante possono cadere sassi o massi, e che potresti trovarne sulla carreggiata. Rallenta, fai attenzione alla strada e non fermarti nel tratto pericoloso. Se la caduta è da destra il segnale ha la parete a destra, se è da sinistra la parete è a sinistra.",q:[["Il segnale avverte che sulla strada possono trovarsi massi caduti",1],["Nel tratto segnalato è opportuno sostare per controllare la parete",0]]},
{id:"bambini",c:"P",n:"Bambini",t:"Questo è il segnale bambini. Avverte che vicino c'è un luogo frequentato da bambini, come una scuola, un giardino o un campo giochi. Devi rallentare e prestare la massima attenzione, perché un bambino può attraversare all'improvviso.",q:[["Il segnale preannuncia un luogo frequentato da bambini",1],["Il segnale indica un attraversamento pedonale sempre regolato da semaforo",0]]},
{id:"animali_dom",c:"P",n:"Animali domestici vaganti",t:"Questo è il segnale di animali domestici vaganti. Avverte che sulla strada possono trovarsi animali come mucche, pecore o cavalli. Rallenta, non suonare il clacson per non spaventarli e, se necessario, fermati.",q:[["Il segnale avverte della possibile presenza di animali domestici sulla strada",1],["Per far allontanare gli animali bisogna usare a lungo il clacson",0]]},
{id:"animali_sel",c:"P",n:"Animali selvatici vaganti",t:"Questo è il segnale di animali selvatici vaganti. Avverte che possono attraversare all'improvviso animali selvatici come cervi, caprioli o cinghiali, soprattutto all'alba, al tramonto e di notte. Modera la velocità e osserva i bordi della strada.",q:[["Il segnale avverte che possono attraversare animali selvatici",1],["Il segnale indica la vicinanza di uno zoo",0]]},
{id:"vento",c:"P",n:"Forte vento laterale",t:"Questo è il segnale di forte vento laterale. Avverte che in quel tratto, per esempio su un viadotto o all'uscita di una galleria, il vento può soffiare forte di lato e spostare il veicolo. Tieni saldo il volante e rallenta, soprattutto se trasporti un carico alto o un portapacchi.",q:[["Il segnale preannuncia un tratto con forte vento laterale",1],["Il segnale indica un aeroporto vicino",0]]},
{id:"semaforo_p",c:"P",n:"Semaforo",t:"Questo è il segnale di pericolo semaforo. Preannuncia un incrocio o un attraversamento regolato da un semaforo, che potrebbe non essere visibile in tempo. Rallenta e preparati a fermarti se la luce è gialla o rossa.",q:[["Il segnale preannuncia un impianto semaforico",1],["Il segnale indica che il semaforo è spento",0]]},
{id:"pl_barriere",c:"P",n:"Passaggio a livello con barriere",t:"Questo è il segnale di passaggio a livello con barriere o semibarriere. Il simbolo è un cancello. Preannuncia un incrocio con la ferrovia protetto da sbarre. Quando le barriere sono in movimento o abbassate, oppure le luci rosse lampeggiano, devi fermarti prima della striscia di arresto. Non devi mai passare a zig zag tra le semibarriere.",q:[["Il segnale preannuncia un passaggio a livello munito di barriere o semibarriere",1],["Con le barriere in movimento si può passare se il treno non è visibile",0]]},
{id:"pl_senza",c:"P",n:"Passaggio a livello senza barriere",t:"Questo è il segnale di passaggio a livello senza barriere. Il simbolo è una locomotiva. Preannuncia un incrocio con la ferrovia senza sbarre. Devi rallentare, guardare e ascoltare: se arriva il treno devi fermarti e dargli la precedenza.",q:[["Il segnale preannuncia un passaggio a livello senza barriere",1],["Il segnale preannuncia una stazione ferroviaria",0]]},
{id:"rotatoria_p",c:"P",n:"Circolazione rotatoria",t:"Questo è il segnale di pericolo circolazione rotatoria. Preannuncia un incrocio a rotatoria: la circolazione gira in senso antiorario intorno all'isola centrale. Rallenta e preparati a dare la precedenza, che di norma è stabilita da un segnale Dare precedenza all'ingresso.",q:[["Il segnale preannuncia un'intersezione con circolazione rotatoria",1],["Nella rotatoria si circola in senso orario",0]]},
{id:"altri",c:"P",n:"Altri pericoli",t:"Questo è il segnale altri pericoli, con il punto esclamativo. Indica un pericolo diverso da quelli che hanno un segnale proprio. Di solito sotto c'è un pannello integrativo che spiega il pericolo, per esempio incidente, ghiaccio o coda. Devi rallentare e prestare la massima attenzione.",q:[["Il segnale indica un pericolo diverso da quelli previsti dagli altri segnali",1],["Il segnale indica la fine di tutti i pericoli",0]]},
{id:"lavori",c:"P",svg:"lavori",n:"Lavori in corso (segnale temporaneo)",t:"Questo è il segnale di lavori. Preannuncia un cantiere sulla strada, con operai, mezzi e possibili restringimenti. Ha il fondo giallo perché è un segnale temporaneo: i segnali gialli dei cantieri prevalgono su quelli permanenti. Riduci la velocità e rispetta le indicazioni del personale.",q:[["Il segnale preannuncia un cantiere stradale",1],["Il fondo giallo indica un segnale temporaneo",1],["Il segnale indica un parcheggio per mezzi da lavoro",0]]},
{id:"strett_temp",c:"P",n:"Strettoia temporanea",t:"Questa è la strettoia simmetrica in versione temporanea, con il fondo giallo. Si usa nei cantieri: la carreggiata si restringe da entrambi i lati per i lavori. Rallenta e fai attenzione ai veicoli in senso opposto.",q:[["Il segnale a fondo giallo è un segnale temporaneo di cantiere",1],["Un segnale temporaneo giallo ha meno valore di quello permanente",0]]},
// ---------------- PRECEDENZA
{id:"dare_prec",c:"R",n:"Dare precedenza",t:"Questo è il segnale Dare precedenza, un triangolo con il vertice in basso. Obbliga a dare la precedenza ai veicoli che circolano sulla strada in cui stai per entrare, sia da destra che da sinistra. Non è obbligatorio fermarsi se la strada è libera, ma devi rallentare e, se arriva qualcuno, fermarti e lasciarlo passare.",q:[["Il segnale obbliga a dare la precedenza a destra e a sinistra",1],["Il segnale obbliga sempre a fermarsi anche se non arriva nessuno",0],["Il segnale è un triangolo con il vertice rivolto verso il basso",1]]},
{id:"stop",c:"R",n:"Fermarsi e dare precedenza (STOP)",t:"Questo è il segnale di STOP, a forma di ottagono. Obbliga a fermarsi sempre, anche se la strada è libera, in corrispondenza della striscia di arresto, e poi a dare la precedenza a tutti i veicoli che circolano sulla strada, da destra e da sinistra. Si mette dove la visibilità è scarsa.",q:[["Il segnale obbliga a fermarsi sempre, anche se non arrivano veicoli",1],["Il segnale obbliga a fermarsi solo se arrivano veicoli da destra",0],["Dopo essersi fermati bisogna dare la precedenza a destra e a sinistra",1]]},
{id:"diritto",c:"R",n:"Diritto di precedenza",t:"Questo è il segnale Diritto di precedenza, un quadrato giallo con bordo bianco messo sul vertice. Indica che la strada che percorri ha la precedenza agli incroci, fino al segnale di fine. Avere la precedenza non significa poter correre: devi comunque essere prudente agli incroci.",q:[["Il segnale indica l'inizio di una strada con diritto di precedenza",1],["Il segnale consente di superare i limiti di velocità",0]]},
{id:"fine_diritto",c:"R",n:"Fine del diritto di precedenza",t:"Questo è il segnale di fine del diritto di precedenza, con una fascia nera obliqua. Da qui la tua strada non ha più la precedenza: agli incroci valgono i segnali presenti oppure la regola generale della precedenza a destra.",q:[["Il segnale indica la fine della strada con diritto di precedenza",1],["Dopo il segnale si ha sempre la precedenza a tutti gli incroci",0]]},
{id:"incrocio_dx",c:"R",n:"Intersezione con precedenza a destra",t:"Questo è il segnale di intersezione con precedenza a destra, un triangolo con una croce nera. Preannuncia un incrocio dove vale la regola generale: devi dare la precedenza ai veicoli che arrivano da destra. È posto prima dell'incrocio, di norma a 150 metri fuori dai centri abitati.",q:[["Il segnale preannuncia un'intersezione in cui si deve dare la precedenza a destra",1],["Il segnale indica un passaggio a livello",0]]},
{id:"dare_alt",c:"R",n:"Dare precedenza nel senso unico alternato",t:"Questo è il segnale Dare precedenza nel senso unico alternato: rotondo con bordo rosso, una freccia nera e una freccia rossa. Lo trovi prima di una strettoia dove si passa uno alla volta. Devi dare la precedenza ai veicoli che arrivano di fronte. Ricorda: la freccia rossa indica chi deve aspettare, cioè tu.",q:[["Il segnale obbliga a dare la precedenza ai veicoli provenienti in senso opposto",1],["Il segnale dà la precedenza a chi lo vede",0]]},
{id:"diritto_alt",c:"R",n:"Diritto di precedenza nel senso unico alternato",t:"Questo è il segnale di diritto di precedenza nel senso unico alternato: quadrato blu con una freccia bianca e una freccia rossa. Nella strettoia sei tu ad avere la precedenza rispetto a chi arriva di fronte. Prima di entrare controlla comunque che il passaggio sia libero.",q:[["Il segnale indica che si ha la precedenza rispetto ai veicoli provenienti in senso opposto",1],["Il segnale è rotondo con bordo rosso",0]]},
// ---------------- DIVIETO
{id:"senso_vietato",c:"D",n:"Senso vietato",t:"Questo è il segnale di senso vietato: rotondo, rosso, con una barra bianca orizzontale. Vieta di entrare in quella strada a tutti i veicoli, in quel senso di marcia. Di solito lo trovi all'uscita di una strada a senso unico.",q:[["Il segnale vieta l'accesso a tutti i veicoli nel senso di marcia",1],["Il segnale vieta il transito in entrambi i sensi di marcia",0]]},
{id:"div_transito",c:"D",n:"Divieto di transito",t:"Questo è il segnale di divieto di transito: rotondo, bianco, con il bordo rosso. Vieta la circolazione a tutti i veicoli, in entrambi i sensi di marcia. Pannelli integrativi possono indicare eccezioni, per esempio i residenti.",q:[["Il segnale vieta il transito a tutti i veicoli in entrambi i sensi",1],["Il segnale vieta solo la sosta",0]]},
{id:"no_auto",c:"D",n:"Transito vietato alle autovetture",t:"Questo è il segnale di transito vietato alle autovetture. Vieta il passaggio alle automobili. Altri veicoli, come motocicli o autocarri, possono passare se non ci sono altri divieti.",q:[["Il segnale vieta il transito alle autovetture",1],["Il segnale vieta il transito a tutti i veicoli",0]]},
{id:"no_moto",c:"D",n:"Transito vietato ai motocicli",t:"Questo è il segnale di transito vietato ai motocicli. Vieta il passaggio ai motocicli. Le automobili possono transitare.",q:[["Il segnale vieta il transito ai motocicli",1],["Il segnale vieta il transito alle biciclette",0]]},
{id:"no_merci",c:"D",n:"Transito vietato ai veicoli per trasporto di cose",t:"Questo è il segnale di transito vietato ai veicoli adibiti al trasporto di cose, cioè gli autocarri. Se sotto c'è un pannello con un peso, per esempio 3,5 tonnellate, il divieto vale solo per i veicoli con massa a pieno carico superiore a quella indicata.",q:[["Il segnale vieta il transito agli autocarri",1],["Il segnale vieta il transito alle autovetture",0]]},
{id:"no_motore",c:"D",n:"Transito vietato a tutti gli autoveicoli e motoveicoli",t:"Questo è il segnale di transito vietato ai veicoli a motore, con un'auto e una moto disegnate. Vieta il passaggio sia agli autoveicoli sia ai motoveicoli. Biciclette e pedoni possono passare.",q:[["Il segnale vieta il transito ad autoveicoli e motoveicoli",1],["Il segnale vieta il transito anche ai pedoni",0]]},
{id:"altezza",c:"D",n:"Limite di altezza",t:"Questo è il segnale di limite di altezza. Vieta il transito ai veicoli che, compreso il carico, superano l'altezza indicata, in questo caso 4 metri. Si trova prima di sottopassi, gallerie o ponti bassi.",q:[["Il segnale vieta il transito ai veicoli più alti di quanto indicato",1],["Il segnale indica la larghezza massima della carreggiata",0]]},
{id:"larghezza",c:"D",n:"Limite di larghezza",t:"Questo è il segnale di limite di larghezza. Vieta il transito ai veicoli più larghi della misura indicata, in questo caso 2 metri e 30, carico compreso.",q:[["Il segnale vieta il transito ai veicoli con larghezza superiore a quella indicata",1],["Il segnale indica l'altezza massima consentita",0]]},
{id:"massa",c:"D",n:"Limite di massa",t:"Questo è il segnale di limite di peso. Vieta il transito ai veicoli che hanno una massa a pieno carico superiore a quella indicata, in questo caso 7,5 tonnellate. Si usa per esempio prima di ponti che non reggono carichi pesanti.",q:[["Il segnale vieta il transito ai veicoli con massa superiore a quella indicata",1],["Il segnale indica la velocità massima per i veicoli pesanti",0]]},
{id:"no_sorpasso",c:"D",n:"Divieto di sorpasso",t:"Questo è il segnale di divieto di sorpasso: un'auto rossa e un'auto nera. Vieta di sorpassare i veicoli a motore, tranne i motocicli senza sidecar e i ciclomotori a due ruote. Vale dal segnale fino al segnale di fine divieto. Le biciclette si possono superare, con prudenza.",q:[["Il segnale vieta di sorpassare i veicoli a motore",1],["Il segnale vieta anche il sorpasso delle biciclette",0],["Il divieto termina con il segnale di fine divieto di sorpasso",1]]},
{id:"fine_sorpasso",c:"D",n:"Fine del divieto di sorpasso",t:"Questo è il segnale di fine divieto di sorpasso: le due auto sono grigie e c'è una fascia nera obliqua. Da qui il sorpasso è di nuovo consentito, ma solo se la manovra è sicura e non ci sono altri divieti, come la linea continua.",q:[["Il segnale indica la fine del divieto di sorpasso",1],["Dopo il segnale si può sorpassare anche con la linea continua",0]]},
{id:"limite",c:"D",n:"Limite massimo di velocità",t:"Questo è il segnale di limite massimo di velocità. Vieta di superare la velocità indicata in chilometri orari, qui 50. Vale fino al segnale di fine limite o fino a un nuovo limite. Il limite è il massimo: con pioggia, nebbia o traffico devi andare più piano.",q:[["Il segnale vieta di superare la velocità indicata",1],["Il segnale indica la velocità minima obbligatoria",0],["Con la strada bagnata può essere necessario andare più piano del limite",1]]},
{id:"fine_limite",c:"D",n:"Fine del limite massimo di velocità",t:"Questo è il segnale di fine limite di velocità, con il numero barrato. Indica che termina quel limite: da qui valgono i limiti generali di quel tipo di strada, per esempio 90 chilometri orari sulle strade extraurbane secondarie.",q:[["Il segnale indica la fine del limite di velocità indicato",1],["Dopo il segnale non esistono più limiti di velocità",0]]},
{id:"div_sosta",c:"D",n:"Divieto di sosta",t:"Questo è il segnale di divieto di sosta: fondo blu, bordo rosso e una sola barra rossa obliqua. Vieta la sosta, ma consente la fermata, cioè una breve sospensione della marcia per far salire o scendere persone, restando pronti a ripartire. Il codice non stabilisce un numero di minuti per la fermata.",q:[["Il segnale vieta la sosta ma consente la fermata",1],["Il segnale vieta anche la fermata",0],["Il segnale ha una sola barra obliqua rossa",1]]},
{id:"div_fermata",c:"D",n:"Divieto di fermata",t:"Questo è il segnale di divieto di fermata: fondo blu, bordo rosso e due barre rosse incrociate. Vieta sia la fermata sia la sosta: non puoi fermarti nemmeno un attimo per far scendere qualcuno. Puoi arrestarti solo per motivi di traffico, per esempio in coda o al semaforo.",q:[["Il segnale vieta sia la fermata sia la sosta",1],["Il segnale consente la fermata per far scendere un passeggero",0],["È consentito arrestarsi per esigenze del traffico",1]]},
// ---------------- OBBLIGO
{id:"obb_dx",c:"O",n:"Direzione obbligatoria a destra",t:"Questo è il segnale di direzione obbligatoria a destra. All'incrocio devi girare a destra: non puoi proseguire dritto né svoltare a sinistra.",q:[["Il segnale obbliga a svoltare a destra",1],["Il segnale consente di proseguire diritto",0]]},
{id:"obb_sx",c:"O",n:"Direzione obbligatoria a sinistra",t:"Questo è il segnale di direzione obbligatoria a sinistra. All'incrocio devi svoltare a sinistra: è vietato andare dritto o a destra.",q:[["Il segnale obbliga a svoltare a sinistra",1],["Il segnale indica un parcheggio a sinistra",0]]},
{id:"obb_dritto",c:"O",n:"Direzione obbligatoria diritto",t:"Questo è il segnale di direzione obbligatoria diritto. Devi proseguire dritto: sono vietate le svolte a destra e a sinistra.",q:[["Il segnale obbliga a proseguire diritto",1],["Il segnale indica una strada a senso unico",0]]},
{id:"cons_dritto_dx",c:"O",n:"Direzioni consentite diritto e destra",t:"Questo è il segnale di direzioni consentite diritto e destra. Puoi proseguire dritto oppure girare a destra. È vietato svoltare a sinistra.",q:[["Il segnale consente di proseguire diritto o di svoltare a destra",1],["Il segnale consente la svolta a sinistra",0]]},
{id:"cons_dritto_sx",c:"O",n:"Direzioni consentite diritto e sinistra",t:"Questo è il segnale di direzioni consentite diritto e sinistra. Puoi andare dritto oppure svoltare a sinistra. È vietato girare a destra.",q:[["Il segnale consente di proseguire diritto o svoltare a sinistra",1],["Il segnale consente la svolta a destra",0]]},
{id:"cons_dx_sx",c:"O",n:"Direzioni consentite destra e sinistra",t:"Questo è il segnale di direzioni consentite destra e sinistra. All'incrocio puoi girare a destra oppure a sinistra, ma non puoi proseguire dritto.",q:[["Il segnale consente di svoltare a destra o a sinistra",1],["Il segnale consente di proseguire diritto",0]]},
{id:"rotatoria_o",c:"O",n:"Rotatoria",t:"Questo è il segnale di obbligo rotatoria: tre frecce bianche in cerchio su fondo blu. Obbliga a circolare intorno all'isola o alla piazza in senso antiorario, cioè tenendo l'isola alla propria sinistra.",q:[["Il segnale obbliga a circolare in senso antiorario intorno all'isola",1],["Il segnale preannuncia un pericolo di rotatoria",0]]},
{id:"pass_dx",c:"O",n:"Passaggio obbligatorio a destra",t:"Questo è il segnale di passaggio obbligatorio a destra, con la freccia obliqua verso il basso a destra. Obbliga a passare a destra di un ostacolo, come uno spartitraffico o un'isola salvagente.",q:[["Il segnale obbliga a passare a destra dell'ostacolo",1],["Il segnale obbliga a svoltare a destra all'incrocio",0]]},
{id:"pass_sx",c:"O",n:"Passaggio obbligatorio a sinistra",t:"Questo è il segnale di passaggio obbligatorio a sinistra. Obbliga a passare a sinistra di un ostacolo, per esempio un cantiere che occupa la parte destra della carreggiata.",q:[["Il segnale obbliga a passare a sinistra dell'ostacolo",1],["Il segnale obbliga a svoltare a sinistra",0]]},
{id:"ciclabile",c:"O",n:"Percorso riservato ai velocipedi (pista ciclabile)",t:"Questo è il segnale di pista ciclabile. Indica un percorso riservato alle biciclette: i ciclisti devono usarlo e gli altri veicoli non possono entrarci né sostarvi.",q:[["Il segnale indica un percorso riservato alle biciclette",1],["Le autovetture possono sostare sulla pista ciclabile per pochi minuti",0]]},
{id:"pedonale",c:"O",n:"Percorso pedonale",t:"Questo è il segnale di percorso pedonale. Indica un percorso riservato ai pedoni: i veicoli non possono circolare né sostare.",q:[["Il segnale indica un percorso riservato ai pedoni",1],["Il segnale indica un attraversamento pedonale",0]]},
{id:"catene",c:"O",n:"Catene per neve obbligatorie",t:"Questo è il segnale di catene per neve obbligatorie. Obbliga a circolare con le catene montate oppure con pneumatici invernali, cioè pneumatici da neve adatti. Vale dal segnale in poi, di solito nel periodo indicato da un pannello.",q:[["Il segnale obbliga ad avere catene montate o pneumatici invernali",1],["Il segnale vieta l'uso delle catene",0]]},
// ---------------- INDICAZIONE
{id:"autostrada",c:"I",n:"Autostrada",t:"Questo è il segnale di autostrada, con fondo verde. Indica l'inizio di un'autostrada. Qui valgono regole speciali: per esempio non possono circolare pedoni, biciclette e ciclomotori. Il limite generale è 130 chilometri orari, 110 con la pioggia; per i neopatentati è 100.",q:[["Il segnale indica l'inizio di un'autostrada",1],["In autostrada possono circolare i ciclomotori",0],["Il colore di fondo verde è tipico dei segnali autostradali",1]]},
{id:"extraurbana",c:"I",n:"Strada extraurbana principale",t:"Questo è il segnale di strada extraurbana principale, con fondo blu e un'auto bianca. Indica una strada a carreggiate separate senza incroci a raso. Valgono regole simili all'autostrada. Il limite generale è 110 chilometri orari, 90 con la pioggia e per i neopatentati.",q:[["Il segnale indica l'inizio di una strada extraurbana principale",1],["Il segnale indica un parcheggio per autovetture",0]]},
{id:"centro",c:"I",svg:"centro",n:"Inizio centro abitato",t:"Questo è il segnale di inizio centro abitato: rettangolo bianco con il nome della località e il simbolo di un paese. Da qui il limite generale di velocità è 50 chilometri orari, salvo cartelli diversi, e valgono le regole dei centri abitati, per esempio il divieto di usare il clacson tranne che in caso di pericolo.",q:[["Dopo il segnale il limite generale di velocità è 50 km/h",1],["Il segnale indica la fine del centro abitato",0]]},
{id:"fine_centro",c:"I",svg:"fine_centro",n:"Fine centro abitato",t:"Questo è il segnale di fine centro abitato, con il nome barrato da una fascia rossa. Da qui finiscono le regole del centro abitato e valgono quelle delle strade extraurbane, per esempio il limite di 90 chilometri orari sulle extraurbane secondarie.",q:[["Il segnale indica la fine del centro abitato",1],["Dopo il segnale il limite resta 50 km/h",0]]},
{id:"ztl",c:"I",svg:"ztl",n:"Zona a traffico limitato (ZTL)",t:"Questo è il segnale di zona a traffico limitato. Indica l'inizio di un'area dove possono entrare solo i veicoli autorizzati, negli orari indicati sotto. Spesso ci sono telecamere che registrano gli accessi: se non sei autorizzato non devi entrare.",q:[["Il segnale indica l'inizio di una zona dove possono accedere solo i veicoli autorizzati",1],["Nella zona a traffico limitato possono entrare tutti i veicoli",0]]},
{id:"zona30",c:"I",n:"Zona a velocità limitata (Zona 30)",t:"Questo è il segnale di zona a velocità limitata. Indica l'inizio di un'area dove non puoi superare i 30 chilometri orari in tutte le strade della zona, fino al segnale di fine zona. Si usa vicino a scuole e quartieri residenziali.",q:[["Il segnale indica una zona in cui non si possono superare i 30 km/h",1],["Il limite vale solo fino al primo incrocio",0]]},
{id:"parcheggio",c:"I",n:"Parcheggio",t:"Questo è il segnale di parcheggio, una P bianca su fondo blu. Indica un'area dove è consentita la sosta dei veicoli. Pannelli sotto il segnale possono indicare a pagamento, orari o categorie.",q:[["Il segnale indica un'area destinata al parcheggio",1],["Il segnale indica una stazione di polizia",0]]},
{id:"park_disabili",c:"I",n:"Parcheggio riservato alle persone con disabilità",t:"Questo è il segnale di parcheggio riservato ai veicoli delle persone con disabilità. Possono sostare solo i veicoli che espongono l'apposito contrassegno. Occupare questi posti senza contrassegno è vietato e comporta la rimozione del veicolo.",q:[["Il segnale indica un parcheggio riservato ai veicoli con contrassegno per persone con disabilità",1],["Chiunque può sostare se si ferma meno di dieci minuti",0]]},
{id:"senza_uscita",c:"I",n:"Strada senza uscita",t:"Questo è il segnale di strada senza uscita: una T bianca con la barra rossa. Indica che la strada non ha sbocco: in fondo non potrai proseguire e dovrai tornare indietro.",q:[["Il segnale indica una strada senza uscita",1],["Il segnale indica un incrocio a T con precedenza",0]]},
{id:"senso_unico",c:"I",n:"Senso unico",t:"Questo è il segnale di senso unico, rettangolare blu con una freccia bianca. Indica che la strada è percorribile in un solo senso, quello della freccia. Nelle strade a senso unico si può sostare anche sul lato sinistro, se non ci sono divieti.",q:[["Il segnale indica una strada a senso unico di circolazione",1],["Il segnale obbliga a svoltare a destra",0]]},
{id:"attr_pedonale",c:"I",n:"Attraversamento pedonale",t:"Questo è il segnale di attraversamento pedonale, quadrato blu con il triangolo bianco e il pedone. Indica il punto dove ci sono le strisce pedonali. Devi fermarti e dare la precedenza ai pedoni che stanno attraversando o che stanno per farlo.",q:[["Il segnale indica un attraversamento pedonale",1],["Ai pedoni sulle strisce bisogna dare la precedenza",1],["Il segnale indica un percorso riservato ai pedoni",0]]},
{id:"ospedale",c:"I",n:"Ospedale",t:"Questo è il segnale di ospedale, la lettera H bianca su fondo blu. Indica la vicinanza di un ospedale. Devi moderare la velocità ed evitare rumori inutili, come il clacson.",q:[["Il segnale indica la vicinanza di un ospedale",1],["Il segnale indica un hotel",0]]},
{id:"rifornimento",c:"I",n:"Rifornimento di carburante",t:"Questo è il segnale di area di servizio con rifornimento di carburante. Indica dove puoi fare benzina o gasolio.",q:[["Il segnale indica un distributore di carburante",1],["Il segnale indica un'officina meccanica",0]]},
{id:"camper",c:"I",n:"Area attrezzata per camper",t:"Questo è il segnale di area attrezzata per camper e caravan. Indica un'area con servizi per autocaravan, per esempio scarico e carico dell'acqua.",q:[["Il segnale indica un'area attrezzata per autocaravan",1],["Il segnale vieta il transito alle autocaravan",0]]},
{id:"sos",c:"I",n:"Colonnina di soccorso (SOS)",t:"Questo è il segnale di colonnina SOS. Indica un telefono di emergenza, di solito in autostrada o in galleria, per chiedere soccorso in caso di guasto o incidente.",q:[["Il segnale indica la presenza di una colonnina per chiamate di soccorso",1],["Il segnale indica un posto di polizia stradale",0]]},
{id:"informazioni",c:"I",n:"Informazioni",t:"Questo è il segnale di informazioni, con la lettera i. Indica un punto dove trovare informazioni turistiche o sulla viabilità.",q:[["Il segnale indica un punto informazioni",1],["Il segnale indica un incrocio pericoloso",0]]},
// ---------------- PANNELLI
{id:"pann_orario",c:"A",n:"Pannello integrativo di orario",t:"Questo è un pannello integrativo di orario, messo sotto un segnale. Indica le ore in cui il segnale vale, qui dalle 8 alle 18. Fuori da quell'orario il divieto non si applica.",q:[["Il pannello indica il periodo di validità del segnale a cui è abbinato",1],["Il pannello indica la distanza dal pericolo",0]]},
{id:"pann_categoria",c:"A",n:"Pannello integrativo di categoria",t:"Questo è un pannello integrativo di categoria, con il simbolo di un veicolo nero su fondo bianco. Indica che il segnale vale solo per quella categoria di veicoli. Se invece sul pannello c'è scritto eccetto, quella categoria è esclusa dal divieto.",q:[["Il pannello limita il segnale alla categoria di veicoli raffigurata",1],["Il pannello indica un parcheggio riservato a quella categoria",0]]},
// ---------------- SEMAFORI E AGENTI
{id:"sem_verde",c:"S",n:"Semaforo: luce verde",t:"La luce verde significa via libera. Puoi passare, ma devi comunque dare la precedenza ai pedoni che attraversano e, se svolti a sinistra, ai veicoli che arrivano di fronte. Non devi entrare nell'incrocio se dall'altra parte c'è coda e rischi di bloccarlo.",q:[["Con il verde si può procedere, rispettando la precedenza ai pedoni",1],["Con il verde si può entrare nell'incrocio anche se non si può sgomberarlo",0]]},
{id:"sem_giallo",c:"S",n:"Semaforo: luce gialla fissa",t:"La luce gialla fissa significa che devi fermarti prima della striscia di arresto, a meno che tu sia così vicino da non poterti fermare in sicurezza. In quel caso devi liberare l'incrocio con prudenza. Il giallo non è un invito ad accelerare.",q:[["Con il giallo fisso bisogna fermarsi, salvo non sia possibile farlo in sicurezza",1],["Con il giallo bisogna accelerare per passare prima del rosso",0]]},
{id:"sem_rosso",c:"S",n:"Semaforo: luce rossa",t:"La luce rossa vieta di superare la striscia di arresto. Devi fermarti e aspettare il verde. Se la striscia non c'è, ti fermi prima dell'incrocio o dell'attraversamento pedonale.",q:[["Con il rosso è vietato superare la striscia di arresto",1],["Con il rosso si può svoltare a destra se non arriva nessuno",0]]},
{id:"sem_freccia",c:"S",n:"Semaforo con freccia verde",t:"La freccia verde accesa consente di andare solo nella direzione indicata dalla freccia, qui a destra. Le altre direzioni seguono le altre luci del semaforo.",q:[["La freccia verde consente di procedere solo nella direzione indicata",1],["La freccia verde consente di andare in tutte le direzioni",0]]},
{id:"ag_braccia",c:"S",n:"Agente: braccia tese orizzontalmente",t:"L'agente con le braccia tese in orizzontale, o con il corpo di profilo, equivale al rosso per chi si trova davanti o dietro di lui, cioè per chi arriva in direzione che incrocia le sue braccia. Equivale al verde per chi arriva dai lati, parallelo alle braccia. Le segnalazioni dell'agente prevalgono su semafori e segnali.",q:[["Con le braccia tese orizzontalmente l'agente ferma chi è di fronte o dietro di lui",1],["Con le braccia tese orizzontalmente l'agente ferma tutti i veicoli in tutte le direzioni",0],["Le segnalazioni dell'agente prevalgono sui semafori",1]]},
{id:"ag_alzato",c:"S",n:"Agente: braccio alzato verticalmente",t:"L'agente con il braccio alzato in verticale significa attenzione: ha lo stesso valore della luce gialla. Chi è già dentro l'incrocio deve sgomberarlo, chi sta arrivando deve fermarsi, salvo non possa farlo in sicurezza.",q:[["Il braccio alzato verticalmente ha lo stesso significato della luce gialla",1],["Il braccio alzato verticalmente indica via libera a tutti",0]]},
{id:"ag_mov",c:"S",n:"Agente: indicazioni con le braccia",t:"L'agente può anche indicare con gesti delle braccia a chi dare il via, e in quale direzione procedere, per esempio invitandoti a svoltare o a proseguire. Devi sempre seguire le sue indicazioni, anche se il semaforo o i cartelli dicono altro.",q:[["Bisogna seguire le indicazioni dell'agente anche se il semaforo indica diversamente",1],["Le indicazioni dell'agente valgono solo se il semaforo è spento",0]]}
];
// Lezioni di teoria (senza foto dedicate). Ogni lezione: titolo, paragrafi letti dalla voce, domande V/F.
const THEORY=[
{id:"orizz",n:"Segnaletica orizzontale",p:["La segnaletica orizzontale è disegnata sulla strada. Le strisce longitudinali bianche dividono le corsie.","La striscia continua non si può superare né calpestare: vieta il sorpasso e il cambio di corsia. La striscia discontinua invece si può superare, se la manovra è sicura.","Se la striscia è doppia, continua e discontinua affiancate, conta quella più vicina a te: se hai vicino la discontinua puoi superarla, se hai vicino la continua no.","La striscia di arresto è una linea bianca trasversale: davanti allo STOP o al semaforo rosso ci si ferma prima di essa. I triangoli bianchi, detti denti di drago, ripetono il dare precedenza.","Le strisce gialle sono temporanee, per i cantieri, e prevalgono su quelle bianche. Le strisce blu delimitano i parcheggi a pagamento, quelle gialle i posti riservati."],q:[["La striscia continua non può essere oltrepassata",1],["Con la doppia striscia si può sorpassare se si ha vicino la striscia discontinua",1],["Le strisce gialle temporanee prevalgono su quelle bianche",1],["La striscia discontinua vieta sempre il cambio di corsia",0],["Le strisce blu delimitano di solito parcheggi a pagamento",1]]},
{id:"prec",n:"Precedenza agli incroci",p:["L'articolo 145 del Codice stabilisce che agli incroci bisogna usare la massima prudenza.","Se non ci sono segnali, si dà la precedenza a chi arriva da destra. Questa è la regola della destra.","Se ci sono segnali, si seguono i segnali: chi ha lo STOP o il Dare precedenza deve lasciar passare gli altri.","Chi svolta a sinistra deve dare la precedenza ai veicoli che arrivano di fronte e vanno dritto o a destra.","Ai veicoli su rotaie, come treni e tram, si dà la precedenza negli attraversamenti, salvo diversa segnalazione, per esempio un semaforo.","Chi esce da un luogo privato, come un cortile o un passo carrabile, deve fermarsi e dare la precedenza a tutti.","Non si deve mai entrare in un incrocio se non si può liberarlo subito, per non bloccare il traffico."],q:[["In assenza di segnali si dà la precedenza ai veicoli provenienti da destra",1],["Chi svolta a sinistra deve dare la precedenza ai veicoli che provengono di fronte",1],["Il tram ha sempre la precedenza, anche quando il semaforo è rosso per lui",0],["Chi esce da un passo carrabile deve dare la precedenza a chi circola sulla strada",1],["Si può entrare in un incrocio anche se non si potrà sgomberarlo",0]]},
{id:"rot",n:"Rotatorie",p:["Nella rotatoria si gira in senso antiorario, tenendo l'isola centrale alla propria sinistra.","Di norma all'ingresso c'è il segnale Dare precedenza: chi entra deve dare la precedenza a chi sta già circolando nella rotatoria, che arriva da sinistra.","Per uscire si mette la freccia a destra prima dell'uscita e si fa attenzione a pedoni e ciclisti."],q:[["Nella rotatoria si circola in senso antiorario",1],["Se all'ingresso c'è il Dare precedenza, si dà la precedenza a chi circola nella rotatoria",1],["Prima di uscire dalla rotatoria si deve azionare l'indicatore di direzione destro",1]]},
{id:"vel",n:"Limiti di velocità",p:["L'articolo 142 fissa i limiti generali. Nei centri abitati il limite è 50 chilometri orari.","Sulle strade extraurbane secondarie e locali il limite è 90. Sulle extraurbane principali è 110. In autostrada è 130.","Con pioggia o neve i limiti scendono: 110 in autostrada e 90 sulle extraurbane principali.","I neopatentati, nei primi tre anni, non possono superare 100 chilometri orari in autostrada e 90 sulle extraurbane principali.","Il limite è il massimo: devi sempre adeguare la velocità alla visibilità, al traffico e alle condizioni della strada."],q:[["Nei centri abitati il limite generale è 50 km/h",1],["In autostrada il limite generale è 130 km/h",1],["Sulle strade extraurbane secondarie il limite generale è 110 km/h",0],["Con la pioggia in autostrada il limite scende a 110 km/h",1],["Il neopatentato in autostrada può andare a 130 km/h",0]]},
{id:"dist",n:"Distanza di sicurezza e frenatura",p:["La distanza di sicurezza è lo spazio da lasciare davanti, che permette di fermarsi senza tamponare chi ci precede.","Deve aumentare con la velocità, con la strada bagnata o ghiacciata, con la nebbia e quando si è stanchi.","Lo spazio di arresto è la somma dello spazio di reazione, percorso mentre il cervello reagisce, e dello spazio di frenatura. Raddoppiando la velocità lo spazio di frenatura diventa circa quattro volte più lungo."],q:[["La distanza di sicurezza deve aumentare con la strada bagnata",1],["Lo spazio di arresto comprende lo spazio percorso durante il tempo di reazione",1],["Raddoppiando la velocità lo spazio di frenatura raddoppia soltanto",0]]},
{id:"sorp",n:"Il sorpasso",p:["Il sorpasso si fa a sinistra. Si può sorpassare a destra solo un veicolo che ha segnalato di voler svoltare a sinistra e si è spostato al centro, oppure il tram, che di regola si sorpassa a destra quando lo spazio lo consente.","Prima di sorpassare bisogna controllare lo specchietto, verificare che nessuno ci stia già sorpassando, mettere la freccia e avere la strada libera per uno spazio sufficiente.","È vietato sorpassare in prossimità di curve, dossi e altri punti con scarsa visibilità, agli incroci non regolati, ai passaggi a livello senza barriere, e sulle strisce pedonali quando un veicolo si è fermato per far passare i pedoni."],q:[["Il sorpasso si effettua di norma a sinistra",1],["È consentito sorpassare a destra un veicolo che svolta a sinistra e si è spostato al centro",1],["È consentito sorpassare in curva se si è veloci",0],["È vietato sorpassare un veicolo fermo per dare la precedenza ai pedoni sulle strisce",1]]},
{id:"sosta",n:"Fermata e sosta",p:["L'articolo 157 distingue tre cose. L'arresto è fermarsi per esigenze del traffico, per esempio in coda.","La fermata è una breve sospensione della marcia per far salire o scendere persone o per esigenze di brevissima durata: il conducente resta al posto di guida, pronto a ripartire.","La sosta è la sospensione della marcia prolungata nel tempo, con possibilità che il conducente si allontani.","Fermata e sosta si fanno sul lato destro della carreggiata, parallelamente al margine. Nelle strade a senso unico anche a sinistra, se resta spazio per la circolazione.","È vietata la sosta, tra l'altro, sulle strisce pedonali, davanti ai passi carrabili, sulle piste ciclabili, agli incroci e in curva."],q:[["La fermata consente al conducente di allontanarsi dal veicolo",0],["Durante la fermata il conducente deve restare pronto a ripartire",1],["Nelle strade a senso unico si può sostare anche sul lato sinistro, se resta spazio",1],["È consentito sostare davanti a un passo carrabile per pochi minuti",0]]},
{id:"luci",n:"Luci del veicolo",p:["Le luci anabbaglianti si usano di notte, in galleria e quando la visibilità è scarsa. Fuori dai centri abitati devono essere accese anche di giorno.","Gli abbaglianti si usano fuori dai centri abitati, quando la strada non è illuminata. Vanno spenti quando si incrocia un altro veicolo o si segue un veicolo da vicino, per non abbagliare.","I proiettori fendinebbia si accendono con nebbia, neve o forte pioggia. Il retronebbia si usa solo con visibilità inferiore a 50 metri.","Le luci di emergenza, le quattro frecce, si usano quando il veicolo è fermo per guasto o per segnalare un pericolo improvviso, per esempio una coda in autostrada."],q:[["Fuori dai centri abitati le luci anabbaglianti devono essere accese anche di giorno",1],["Gli abbaglianti vanno spenti quando si incrocia un altro veicolo",1],["Il retronebbia si accende con visibilità inferiore a 50 metri",1],["In galleria si può circolare a luci spente",0]]},
{id:"sicurezza",n:"Cinture, bambini e dispositivi",p:["Le cinture di sicurezza sono obbligatorie per il conducente e per tutti i passeggeri, davanti e dietro.","I bambini di statura inferiore a 1 metro e 50 devono viaggiare su un seggiolino o un adattatore omologato, adatto al loro peso. Il seggiolino rivolto all'indietro non si mette davanti se l'airbag passeggero è attivo.","Per i bambini sotto i 4 anni è obbligatorio il dispositivo antiabbandono.","Durante la guida è vietato usare il telefono con le mani: si possono usare solo vivavoce o auricolare, purché non richiedano l'uso delle mani."],q:[["Le cinture sono obbligatorie anche per i passeggeri posteriori",1],["I bambini sotto 1,50 m devono usare un sistema di ritenuta adatto",1],["Si può usare il telefono tenendolo in mano se si va piano",0]]},
{id:"alcol",n:"Alcol, droghe e stanchezza",p:["Il limite di alcol nel sangue è 0,5 grammi per litro.","Per i neopatentati nei primi tre anni, per chi ha meno di 21 anni e per i conducenti professionali il limite è zero.","Guidare dopo aver assunto droghe è sempre vietato. Anche alcuni farmaci possono ridurre l'attenzione: bisogna leggere il foglietto illustrativo.","La stanchezza e il sonno rallentano i riflessi: nei viaggi lunghi bisogna fare una pausa almeno ogni due ore."],q:[["Il limite generale del tasso alcolemico è 0,5 g/l",1],["Il neopatentato può guidare con un tasso alcolemico di 0,4 g/l",0],["Alcuni farmaci possono ridurre la capacità di guida",1]]},
{id:"incidente",n:"Incidente ed emergenza",p:["In caso di incidente bisogna fermarsi, mettere in sicurezza il luogo e prestare assistenza ai feriti. Il numero unico di emergenza è il 112.","Il triangolo va posto ad almeno 50 metri dal veicolo fuori dai centri abitati, in modo che sia visibile da almeno 100 metri.","Chi scende dal veicolo fuori dai centri abitati, di notte o con scarsa visibilità, deve indossare il giubbotto o le bretelle retroriflettenti.","Non bisogna spostare un ferito, salvo pericolo immediato come un incendio. Al motociclista ferito non si toglie il casco."],q:[["Fuori dai centri abitati il triangolo va posto ad almeno 50 metri dal veicolo",1],["A un motociclista ferito bisogna togliere subito il casco",0],["Il numero unico di emergenza europeo è il 112",1]]},
{id:"autos",n:"Autostrada e strade extraurbane",p:["In autostrada si entra dalla corsia di accelerazione, adeguando la velocità e dando la precedenza a chi è già in carreggiata.","Si circola sulla corsia libera più a destra. Le corsie di sinistra servono per il sorpasso.","La corsia di emergenza si usa solo in caso di guasto o di malore: è vietato percorrerla o sostarvi per altri motivi.","È vietata l'inversione di marcia e la retromarcia. Se si sbaglia uscita si prosegue fino alla successiva."],q:[["In autostrada si deve circolare sulla corsia libera più a destra",1],["In autostrada è consentita la retromarcia se si sbaglia uscita",0],["La corsia di emergenza si può usare in caso di guasto",1]]},
{id:"pedoni",n:"Pedoni e ciclisti",p:["Bisogna dare la precedenza ai pedoni che attraversano sulle strisce o che stanno per farlo. Davanti alle strisce si rallenta.","Agli incroci, chi svolta deve dare la precedenza ai pedoni che attraversano la strada in cui entra.","Per superare un ciclista bisogna lasciare uno spazio laterale adeguato; dove possibile almeno un metro e mezzo.","Il ciclista che conduce la bicicletta a mano è assimilato al pedone."],q:[["Si deve dare la precedenza ai pedoni che stanno per attraversare sulle strisce",1],["Il ciclista che conduce la bicicletta a mano è assimilato al pedone",1],["Per superare un ciclista basta lasciare pochi centimetri",0]]},
{id:"patente",n:"Patente, documenti e punti",p:["Per guidare bisogna avere con sé la patente e la carta di circolazione del veicolo. Il veicolo deve essere assicurato e revisionato.","La patente ha 20 punti. Le infrazioni tolgono punti; due anni senza infrazioni danno due punti in più. Se i punti finiscono bisogna rifare l'esame di idoneità, cioè la revisione.","La revisione dell'auto nuova si fa dopo quattro anni dall'immatricolazione, poi ogni due anni.","La patente B fino a 50 anni si rinnova ogni 10 anni, poi con scadenze più frequenti."],q:[["La patente ha un punteggio iniziale di 20 punti",1],["La prima revisione dell'auto nuova si fa dopo quattro anni",1],["Si può guidare senza assicurazione per brevi tratti",0]]},
{id:"meteo",n:"Guida con cattivo tempo",p:["Con la pioggia aumenta lo spazio di frenatura e può verificarsi l'aquaplaning: le gomme perdono contatto con l'asfalto per uno strato d'acqua. In quel caso non si frena di colpo: si lascia l'acceleratore e si tiene dritto il volante.","Con la nebbia si accendono anabbaglianti e fendinebbia, si riduce molto la velocità e si aumenta la distanza.","Con neve e ghiaccio servono catene o pneumatici invernali; si usano marce alte e accelerazioni dolci."],q:[["In caso di aquaplaning bisogna frenare bruscamente",0],["Con la nebbia è opportuno aumentare la distanza di sicurezza",1],["Pneumatici consumati aumentano il rischio di aquaplaning",1]]},
{id:"veicolo",n:"Il veicolo e la manutenzione",p:["Gli pneumatici devono avere un battistrada di almeno 1,6 millimetri. Una pressione troppo bassa aumenta i consumi e riduce la tenuta.","Bisogna controllare regolarmente l'olio, il liquido dei freni, il liquido di raffreddamento e le luci.","Se si accende la spia rossa dell'olio o dei freni bisogna fermarsi appena possibile in sicurezza."],q:[["Lo spessore minimo del battistrada è 1,6 mm",1],["Una pressione bassa degli pneumatici riduce i consumi",0],["Con la spia rossa dei freni accesa si può proseguire il viaggio normalmente",0]]}
];
